-- Agent 安全知识库扩充：新增 30 篇文档、90 个检索片段。
-- 使用前提：已执行 sql/module/26-agent-rag.sql。
-- 数据来源为通用实验室安全教育资料的项目化整理，正式部署前应替换或核对为本校制度。
-- 可重复执行。
USE bishe_schema;
SET NAMES utf8mb4 COLLATE utf8mb4_general_ci;

START TRANSACTION;


ON DUPLICATE KEY UPDATE
keywords = VALUES(keywords),
content = VALUES(content),
status = VALUES(status);

COMMIT;

SELECT COUNT(*) AS document_count, SUM(CHAR_LENGTH(c.content)) AS content_chars
FROM knowledge_document d
JOIN knowledge_chunk c ON c.document_id = d.id
WHERE d.status = '0' AND c.status = '0';
