INSERT INTO knowledge_chunk (id, document_id, chunk_no, keywords, content) VALUES
(11001, 1011, 1, '强酸 硫酸 盐酸 硝酸 沾到皮肤 沾到手上 皮肤接触 溅到 急救', '强酸溅到皮肤后应立即脱去被污染的衣物和饰品，用流动清水持续冲洗受伤部位至少十五分钟，避免用力擦拭或自行使用大量碱液中和。面部或眼部受到喷溅时应优先使用洗眼器和紧急喷淋。冲洗期间尽快通知指导教师，并准备化学品安全技术说明书供医护人员判断。'),
(11002, 1011, 2, '强碱 氢氧化钠 氢氧化钾 皮肤 沾到 溅到 冲洗', '强碱造成的组织损伤可能逐渐加重，即使当时疼痛不明显也不能忽视。应立即用大量清水冲洗，不要用酸性溶液直接中和。若皮肤出现发白、滑腻、起泡或破溃，应覆盖清洁敷料并尽快就医。污染衣物不得带回生活区域，应按规定单独处理。'),
(11003, 1011, 3, '酸碱灼伤 急救 报告 就医 事故记录', '化学品灼伤后应报告实验室负责人，记录化学品名称、浓度、接触时间和已采取的急救措施。就医时携带安全技术说明书，不要隐瞒实际接触情况。事故处理完毕后应检查容器是否破损、标签是否清晰，并评估是否需要调整操作流程或补充个人防护。'),
(11011, 1012, 1, '水银 汞 温度计 打碎 破碎 泄漏 撤离 通风', '水银温度计或含汞器皿破碎后应立即停止实验，让无关人员离开并打开门窗通风，关闭空调和加热设备。不要用手直接接触汞珠，也不要用普通吸尘器清扫，因为加热和气流会使汞蒸气扩散。应使用专用汞处理工具或硫粉覆盖，再由实验室管理员按危险废物要求收集。'),
(11012, 1012, 2, '水银珠 汞珠 收集 硫粉 密闭 容器', '散落的汞珠可从外向内缓慢聚集，使用硬纸片、注射器或专用吸附材料收集，避免扫帚将汞珠打散。难以收集的细小残留可覆盖硫粉并保持通风。所有污染材料应放入明确标识的密闭容器，不能倒入下水道或普通垃圾桶。'),
(11013, 1012, 3, '汞暴露 头晕 恶心 报告 医学观察 污染区', '参与处置的人员应佩戴合适手套和防护用品，处置后彻底洗手。若出现头晕、恶心、咳嗽等不适，或怀疑长时间处于高浓度汞蒸气环境，应及时报告并接受医学评估。污染区域在检测确认安全前不得恢复实验。'),
(11021, 1013, 1, '有机溶剂 酒精 乙醇 丙酮 甲醇 洒了 洒在 实验台 泄漏 易燃 防火', '乙醇、丙酮、甲醇等有机溶剂洒漏时应立即远离火源，关闭附近加热设备，避免启停可能产生火花的电器，并打开通风设施。少量泄漏可由受过训练的人员佩戴护目镜、手套和实验服后使用惰性吸附材料处理，不能使用抹布大面积挥散。'),
(11022, 1013, 2, '有机溶剂 酒精 洒在 实验台 泄漏 吸附 通风 围堵 收集 密闭 废物', '处理泄漏时应从外向内围堵，防止液体流入地漏。使用砂土、蛭石或专用吸附棉吸收后，将污染吸附物装入有标签的密闭容器，按危险废物处理。被污染的台面和地面还应使用适宜清洁剂擦拭，并保持通风直至气味消失。'),
(11023, 1013, 3, '大量泄漏 易燃液体 撤离 报警 火灾', '泄漏量较大、容器持续外泄或已经形成可燃蒸气时，应立即撤离并报警，不要单独返回处理。若液体流向高温设备或电源附近，应扩大警戒范围。事故后应检查溶剂瓶盖、二次容器和储存柜，防止同类泄漏再次发生。'),
(11031, 1014, 1, '通风柜 使用 视窗 高度 风速 检查', '使用通风柜前应确认风机运行、指示装置正常，视窗保持在推荐高度并留出足够操作空间。实验过程中身体不要伸入柜内，头部和上半身应保持在柜外。出现警报、风速不足或异味回流时应停止操作并报告，不能继续依靠通风柜处理有毒或挥发性物质。'),
(11032, 1014, 2, '通风柜 物品 存放 气流 堵塞 台面', '通风柜内只放置本次实验必需物品，避免大量试剂瓶和纸箱阻挡气流。设备应垫高并远离柜体后缘，以减少气流扰动。通风柜不能作为长期化学品储存柜使用，实验结束后应及时清理台面、关闭容器并保持柜内整洁。'),
(11033, 1014, 3, '通风柜 故障 报警 维护 登记', '通风柜发生风速低、异响、排风中断或玻璃门损坏时应停止使用并设置明显提示。故障应由专业维护人员检查，修复后确认气流恢复正常再启用。日常检查、维修和异常情况应登记，便于追溯设备状态。'),
(11041, 1015, 1, '气体钢瓶 气瓶 固定 链条 防倾倒 支架', '气体钢瓶必须直立放置，并用链条、卡箍或专用支架固定在墙面或坚固支架上，防止倾倒和瓶阀折断。钢瓶应远离热源、火源和人员密集区域，不得横放滚动。搬运时使用专用手推车，不要抓住瓶阀或压力表拖拽。'),
(11042, 1015, 2, '钢瓶 搬运 瓶帽 保护 碰撞 减压阀', '运输钢瓶时应安装瓶帽和防震圈，轻装轻卸，避免撞击、跌落和暴晒。使用前检查瓶体、瓶阀、软管和减压阀是否完好，减压阀不得混用不同气体。开启瓶阀应缓慢进行，人员站在阀门侧面，不能正对出气口。'),
(11043, 1015, 3, '钢瓶 泄漏 异味 阀门 撤离 报告', '发现钢瓶泄漏、阀门损坏或异常气味时，应立即远离泄漏区域并通知管理员。只有在明确气体性质和确保安全的情况下，才可由受训人员关闭阀门。可燃或有毒气体大量泄漏时应撤离并报警，不得启闭普通电器或使用明火寻找漏点。'),
(11051, 1016, 1, '氧气瓶 乙炔瓶 分开 距离 明火 可燃气体 助燃气体', '氧气是助燃气体，乙炔是高度易燃气体，二者必须分开存放并在使用点保持规定的安全距离。钢瓶应固定直立，远离明火、热源和电气设备。作业区域不得存放油脂类物质，氧气瓶阀和管路严禁接触油脂。'),
(11052, 1016, 2, '乙炔 回火 防止 回火防止器 软管 检漏', '乙炔系统应安装合格的回火防止器，软管和接头应定期检查，宜使用肥皂水检漏，禁止用明火试漏。点火和熄火应遵循设备操作规程，发现回火、软管焦化或异常压力时立即关闭气源并停止使用。'),
(11053, 1016, 3, '气体泄漏 火灾 撤离 报警 禁止 电器', '发生氧气或乙炔泄漏时，应立即停止作业、远离火源并按疏散路线撤离。未确认安全前不得开关普通电器或使用手机靠近泄漏点。若已经着火或发生爆炸风险，应立即报警并交给消防和专业人员处置。'),
(11061, 1017, 1, '试管 加热 管口 朝向 夹持 沸腾 喷出', '加热试管时应使用试管夹夹持中上部，管口不得朝向自己或他人，并保持适当倾斜和轻微移动。液体体积不宜超过试管容积的三分之一，加热前检查试管是否有裂纹。发现剧烈沸腾、喷溅或异常破裂时应立即停止加热并远离。'),
(11062, 1017, 2, '玻璃器皿 破损 裂纹 割伤 割破 处理', '玻璃器皿出现裂纹、缺口或受热不均后不得继续使用。被玻璃割伤时应先停止实验，用流动清水冲洗伤口并去除可见异物，使用清洁敷料加压止血。伤口较深、持续出血或接触化学品时应立即就医。'),
(11063, 1017, 3, '碎玻璃 清理 锐器 废物 手套 扫帚', '清理碎玻璃时应佩戴防割手套并设置警示，使用镊子、硬纸板或扫帚收集，避免徒手抓取。碎玻璃和污染锐器应放入专用锐器盒或耐刺穿容器，不能混入普通垃圾。清理后检查台面和地面是否仍有细小碎片。'),
(11071, 1018, 1, '低温冰箱 超低温 冻存 防冻手套 护目镜 低温防护', '从超低温冰箱取放样本时应佩戴低温防冻手套、护目镜和实验服，动作迅速但不要奔跑。金属托盘、冻存架和样本管可能瞬间粘住皮肤，不能徒手接触。取出的样本应放在冰盒或指定转运容器中，避免反复冻融。'),
(11072, 1018, 2, '冻存管 爆裂 密封 容器 冻伤 处置', '冻存管不能装得过满，应使用适合低温的管材并留有膨胀空间。取用可能膨胀的密封管时应在安全位置缓慢解冻并佩戴面屏，防止管体爆裂。发生冻伤时用温水缓慢复温，不要揉搓或用热水、明火直接加热。'),
(11073, 1018, 3, '低温冰箱 报警 温度 样本 停电 报告', '低温冰箱出现温度报警、结霜严重、门封不严或停电时应立即报告管理员，尽量减少开门次数并转移关键样本。不得自行敲击或强力关闭故障门体。恢复正常后应记录温度波动和样本状态。'),
(11081, 1019, 1, '烘箱 干燥箱 易燃 有机溶剂 乙醇 禁止 爆炸', '普通烘箱不得烘干含乙醇、丙酮等易燃有机溶剂的物品，也不得放入可能产生可燃蒸气的密闭容器。待烘物品应预先去除明显溶剂并确认温度上限，烘箱周围不得堆放纸箱和可燃物。需要处理含溶剂样品时应使用符合要求的专用设备。'),
(11082, 1019, 2, '烘箱 温度 超温 密闭容器 压力 玻璃', '使用前应核对设定温度、温控状态和通风条件，不能超过器皿或样品的耐温范围。密闭玻璃瓶、带塞容器和可能产生压力的物品不得直接放入烘箱。运行中闻到焦味、听到异响或温度异常时应断电并报告。'),
(11083, 1019, 3, '真空干燥箱 真空 泄压 开门 安全', '真空干燥箱在恢复常压前不得强行开门，取出物品时应佩戴隔热手套并防止热表面烫伤。设备长期不用应断电、清洁并保持门体微开。温控、真空密封或超温保护故障修复前不得继续使用。'),
(11091, 1020, 1, '停电 突然 黑暗 设备 停止 实验 人员安全', '实验过程中突然停电时应先保持冷静，停止加样、加热和加压等操作，避免在黑暗中奔跑。使用手电照明，确认人员安全并关闭可能自行恢复运行的设备开关。涉及有毒气体、正在反应的体系或高温高压设备时，应立即通知教师和管理员。'),
(11092, 1020, 2, '停电 冰箱 培养箱 UPS 样本 温度', '停电可能影响低温冰箱、培养箱和服务器等关键设备。应确认不间断电源是否工作，减少冰箱开门并记录温度变化；不要擅自连接大功率临时电源。重要样本和培养物需要转移时，应按实验室应急预案执行。'),
(11093, 1020, 3, '恢复供电 设备 检查 重启 报告 记录', '恢复供电后不要立即同时启动全部设备，应先检查电源、线路、温控和报警状态，再按操作规程逐台恢复。异常气味、冒烟或设备报警时应保持断电并报告。停电时间、影响设备和样本状态应形成记录。'),
(11101, 1021, 1, '化学品标签 GHS 标识 危险 象形图 名称 浓度', '所有化学品容器都应保持标签清晰，注明名称、浓度、配制日期、配制人和必要的危险提示。不得使用饮料瓶或没有标签的容器盛装试剂。发现标签脱落、模糊或内容变更时，应立即停止使用并重新确认。'),
(11102, 1021, 2, '安全技术说明书 SDS MSDS 查阅 危害 急救', '使用新化学品前应查阅安全技术说明书，了解危害分类、暴露限值、个体防护、泄漏处置和急救措施。安全技术说明书应存放在实验人员能够及时获取的位置。不同批次或不同浓度发生变化时，应重新核对相关信息。'),
(11103, 1021, 3, '二次容器 分装 标签 混放 识别 记录', '分装化学品应使用相容容器并立即贴标签，不得把剩余试剂倒回原瓶。多个小容器应放入二次容器，防止倾倒后相互反应。标签信息不完整或无法确认成分的化学品不得继续使用，应交由管理员鉴别处理。'),
(11111, 1022, 1, '易燃液体 储存 乙醇 丙酮 乙醚 限量 防爆冰箱', '乙醇、丙酮、乙醚等易燃液体应存放在阴凉、通风、远离火源和氧化剂的专用柜中，并控制单次存放量。需要低温保存的易燃液体必须使用防爆冰箱，不能放入普通家用冰箱。容器应密闭、标签清楚并留出热膨胀空间。'),
(11112, 1022, 2, '易燃液体 静电 接地 转移 容器 火花', '大量转移易燃液体时应使用合适容器和接地措施，避免快速倾倒产生静电。附近不得有明火、电烙铁、加热板或可能产生火花的设备。发现容器渗漏、鼓胀或气味异常时，应停止使用并转移到安全位置。'),
(11113, 1022, 3, '易燃液体 着火 灭火器 干粉 二氧化碳 撤离', '少量易燃液体着火时，在确保人员安全的前提下可切断附近能源并使用干粉或二氧化碳灭火器。不得用水柱直接冲击液面，以免火焰扩散。火势扩大、产生浓烟或有容器受热时，应立即撤离并报警。'),
(11121, 1023, 1, '腐蚀性 化学品 酸 碱 储存 分开 二次容器', '盐酸、硫酸、硝酸、氢氧化钠等腐蚀性化学品应存放在耐腐蚀专用柜中，酸和碱分开，氧化性酸与还原性物质分开。液体容器应放入二次托盘，货架高度适中，避免拿取时倾倒。柜门应保持关闭并张贴警示标识。'),
(11122, 1023, 2, '硝酸 盐酸 混放 反应 有毒气体 禁止', '不同腐蚀性化学品混放可能产生有毒气体或剧烈反应，例如硝酸与某些有机物、盐酸与氧化剂接触存在风险。未经风险评估不得把废液或剩余试剂随意合并。转移和分装时使用相容的漏斗、容器和标签。'),
(11123, 1023, 3, '腐蚀品 泄漏 中和 专业 处置 报告', '腐蚀性液体泄漏时，应设置警戒并佩戴合适防护用品。中和处理必须依据化学品性质并使用指定试剂，不能把酸碱随意混合。大量泄漏或与不相容物质接触时应撤离并通知专业人员处置。'),
(11131, 1024, 1, '氧化剂 还原剂 分开 储存 反应 高锰酸钾 过氧化氢', '高锰酸钾、过氧化氢、硝酸盐等氧化剂应与还原剂、有机溶剂和可燃材料分开存放，避免受热、撞击和阳光直射。容器应保持密封，标签注明浓度和日期。氧化剂泄漏后不得使用可燃吸附材料草率处理。'),
(11132, 1024, 2, '过氧化物 久置 爆炸 风险 检查 报废', '乙醚等可能形成过氧化物的溶剂应关注生产日期和储存时间，定期检查是否出现结晶、浑浊或瓶盖异常。超过安全期限或怀疑形成过氧化物的试剂不得擅自开启或蒸馏，应按危险化学品报废要求处理。'),
(11133, 1024, 3, '氧化剂 还原剂 意外混合 放热 气体 撤离', '发现氧化剂与还原剂意外混合、温度快速升高或产生刺激性气体时，应立即停止操作并撤离附近人员。不要盲目加水或用手触碰容器，应报告管理员并按安全技术说明书处置。'),
(11141, 1025, 1, '有毒化学品 通风柜 防护 手套 兼容 吸入', '使用有毒、易挥发或粉尘类化学品时应在通风柜或局部排风设施内操作，佩戴与化学品相容的手套、护目镜和实验服。不能凭气味判断是否安全，也不能用嘴吸移液。操作结束后应及时清理台面并洗手。'),
(11142, 1025, 2, '手套 兼容性 破损 更换 渗透 防护', '不同手套材料对不同化学品的防护能力不同，应查阅兼容性表选择合适手套。手套出现破损、污染或长时间接触后应及时更换，摘手套时避免外表面接触皮肤。乳胶手套不能作为所有有机溶剂和腐蚀品的通用防护。'),
(11143, 1025, 3, '有毒 粉尘 称量 密闭 清洁 废物', '称量有毒粉尘时应在通风柜或密闭称量装置中完成，使用专用药匙和托盘，减少扬尘。洒落粉末应使用湿法或吸附材料收集，不能使用压缩空气吹散。污染材料按危险废物处理，操作区域完成清洁后方可离开。'),
(11151, 1026, 1, '危险气体 泄漏 有毒 可燃 撤离 报警 阀门', '发现有毒或可燃气体泄漏时，应立即停止作业、远离泄漏点并通知周围人员。不要开关普通电器、使用明火或手机靠近泄漏区域。只有确认气体性质、泄漏位置且佩戴合适防护后，才可由受训人员尝试关闭上游阀门。'),
(11152, 1026, 2, '气体报警 探测器 通风 疏散 警戒', '气体报警器响起时，应按照预案撤离并设置警戒，不能因为暂时没有气味就返回。实验室通风系统和防爆设备应由专业人员根据气体性质使用。消防或应急人员到达后，应提供气体种类、钢瓶位置和人员情况。'),
(11153, 1026, 3, '泄漏后 检查 检漏 检修 恢复 记录', '泄漏处置完成后应由专业人员检查钢瓶、阀门、管路和报警器，确认无残余泄漏并充分通风后才能恢复使用。检漏应使用肥皂水或专用仪器，不能用明火。事故原因、维修结果和恢复时间应记录。'),
(11161, 1027, 1, '洗眼器 紧急喷淋 位置 检查 通道 畅通', '进入实验室后应确认洗眼器和紧急喷淋的位置，保持通道畅通，不在设备周围堆放物品。洗眼器和喷淋应按规定定期试水，确保出水正常。发现水压不足、喷头堵塞或水质异常时应及时报修。'),
(11162, 1027, 2, '洗眼器 使用 冲洗 15分钟 隐形眼镜', '化学品进入眼睛后应立即用洗眼器或流动清水冲洗至少十五分钟，翻开眼睑确保充分冲洗。不要揉眼，不要使用药品或眼药水代替冲洗。佩戴隐形眼镜时不要强行摘取，应在持续冲洗的同时尽快接受医疗处理。'),
(11163, 1027, 3, '紧急喷淋 衣物 污染 冲洗 保暖 就医', '身体大面积污染时应使用紧急喷淋脱去污染衣物并持续冲洗，注意保护隐私和保暖。冲洗完成后用清洁材料覆盖受伤部位，并携带化学品名称和安全技术说明书就医。使用过的区域应清理并记录事故。'),
(11171, 1028, 1, '灭火器 类型 干粉 二氧化碳 水基 适用 火灾', '实验室应根据火灾类型配置灭火器。干粉灭火器适用范围较广，二氧化碳灭火器适合精密电器，不能用水直接扑救带电设备和活泼金属火灾。使用前应确认灭火器压力正常、保险销完好并在有效期内。'),
(11172, 1028, 2, '灭火器 使用 PASS 拔销 对准 根部 扫射', '使用手提式灭火器时应先拔掉保险销，站在上风方向，将喷嘴对准火焰根部，压下手柄左右扫射。保持安全撤离路线，不要站在可能爆炸的容器正前方。灭火后继续观察，防止复燃。'),
(11173, 1028, 3, '火势扩大 撤离 报警 灭火器 不返回', '只应在火势较小且人员有安全退路时尝试使用灭火器。火焰迅速蔓延、产生大量浓烟、容器受热或涉及不明化学品时，应立即撤离并报警。撤离后不得返回取物或寻找同伴，应向救援人员说明情况。'),
(11181, 1029, 1, '火警 报警 初期火灾 大声呼喊 消防 119', '发现火情应立即大声呼喊并向实验室负责人报告，根据校园应急流程触发火警。初期小火可在确保退路和防护的前提下使用合适灭火器材处置。火势无法控制时要立即拨打火警电话并撤离，不能为了保存实验数据延误逃生。'),
(11182, 1029, 2, '火灾 电源 气体 关阀 有条件 安全', '离开前只有在安全且经过训练的情况下，才可关闭相关电源和气体阀门。不要穿过浓烟或火焰去关闭设备。涉及压缩气体钢瓶、活泼金属或不明化学品火灾时，应交给消防专业人员处置，并向其说明现场危险物。'),
(11183, 1029, 3, '火灾 复燃 警戒 消防 调查 记录', '火灾扑灭后不得立即恢复实验，应等待消防或安全人员确认现场无复燃和有毒烟气风险。事故现场应保持警戒，配合调查并记录起火位置、涉及化学品和处置过程。未经许可不得移动关键物证。'),
(11191, 1030, 1, '疏散 路线 集合点 电梯 浓烟 逃生', '实验室火灾或危险气体泄漏时，应沿最近的安全出口和疏散指示撤离，不乘坐电梯，不穿越浓烟区域。烟雾较大时保持低姿，使用湿毛巾或衣物遮住口鼻只能短暂减少烟雾吸入，不能代替快速撤离。'),
(11192, 1030, 2, '集合点 清点 人数 失联 报告 救援', '到达安全集合点后应按班级或实验室清点人数，向现场负责人报告失联人员位置和可能接触的危险物。不要自行返回搜救，应把信息提供给消防救援人员。保持通讯畅通并服从现场指挥。'),
(11193, 1030, 3, '疏散演练 路线 熟悉 通道 照明', '实验人员应熟悉所在楼层的两条疏散路线、集合点和紧急照明位置。安全通道和防火门不得堆放物品或上锁阻挡。参加疏散演练后应了解本实验室的特殊风险和集合点名方式。'),
(11201, 1031, 1, '误食 吃进 化学品 口腔 漱口 不要催吐', '误食化学品后应立即停止进食，用清水漱口，不要自行大量饮水或盲目催吐。腐蚀性物质、有机溶剂和起泡性物质催吐可能造成二次伤害，必须根据安全技术说明书和急救人员指导处理。应尽快就医并携带化学品信息。'),
(11202, 1031, 2, '误食 意识不清 窒息 急救 120', '若误食者出现意识不清、呼吸困难、抽搐或呕吐，应保持呼吸道通畅并立即呼叫急救。不要向意识不清者强行灌水或塞入食物。呕吐物可能含有危险化学品，清理时应佩戴防护用品并避免污染扩散。'),
(11203, 1031, 3, '误食 报告 包装 样本 医疗 记录', '就医时应说明化学品名称、浓度、估计摄入量和时间，最好携带原包装或标签。事故应报告实验室负责人并记录处置过程。食品和饮料不得带入实验区域，避免误拿试剂容器。'),
(11211, 1032, 1, '吸入 有毒气体 刺鼻 头晕 新鲜空气 撤离', '吸入刺激性或有毒气体后应立即离开污染区域，转移到空气新鲜处，保持呼吸道通畅并通知教师。不要在没有防护的情况下进入泄漏区救人。若出现持续咳嗽、胸闷、呼吸困难、头晕或意识改变，应立即呼叫急救。'),
(11212, 1032, 2, '吸入 救援 呼吸防护 正压 禁止 盲目施救', '有毒气体环境中救援需要专业呼吸防护设备，普通口罩或湿毛巾不能提供可靠保护。发现同伴倒伏时应先报警并关闭可能的泄漏源，不能盲目进入。救援人员应与现场保持沟通并采取防爆措施。'),
(11213, 1032, 3, '吸入后 观察 迟发 肺水肿 就医 报告', '部分刺激性气体造成的肺部损伤可能延迟出现，即使症状缓解也应接受医学观察。就医时说明气体种类、暴露时间和是否曾进入密闭空间。实验室应检查通风和泄漏原因，修复前停止相关操作。'),
(11221, 1033, 1, '生物 泄漏 菌液 培养皿 打翻 消毒 警戒', '培养皿打翻、菌液洒出或生物样本泄漏时，应立即停止人员流动并设置警戒，打开通风但避免扬尘。由经过培训的人员佩戴手套、实验服和护目镜，用吸水材料覆盖后从外围向中心清理，再使用适用消毒剂作用足够时间。'),
(11222, 1033, 2, '生物泄漏 消毒剂 浓度 接触时间 清理 锐器', '消毒剂应按说明配制并保证接触时间，不能只喷洒后立即擦掉。清理过程中避免产生气溶胶，不得用高压水枪冲洗。若泄漏物中混有针头、碎玻璃等锐器，应使用工具收集并放入锐器盒。'),
(11223, 1033, 3, '生物 暴露 报告 医疗 观察 废物 灭菌', '人员皮肤、黏膜或伤口接触生物样本后，应立即冲洗并按暴露流程报告，接受医学评估。污染材料应双层包装、标识并按规定灭菌或作为生物废物处理。泄漏区域完成消毒和记录后才能恢复使用。'),
(11231, 1034, 1, '针头 锐器 刺伤 扎到 回套 禁止 锐器盒', '使用过的针头、刀片和破碎玻璃必须立即放入耐刺穿、防渗漏的锐器盒，禁止徒手回套针帽、弯折或折断针头。锐器盒应放在使用点附近并保持开口高度合适，装到规定容量后及时封口更换。'),
(11232, 1034, 2, '刺伤 扎伤 伤口 冲洗 报告 暴露', '被污染针头或其他锐器刺伤后，应立即停止操作，用流动清水和肥皂清洗伤口，不要用力挤压。尽快报告实验室负责人并按职业暴露流程接受评估。应记录锐器来源、样本性质和暴露时间。'),
(11233, 1034, 3, '锐器盒 满溢 封口 转运 标识 培训', '锐器盒不得敲打、挤压或反复倒出内容物，装满后由专人封口、标识和转运。清理人员应接受防刺伤培训，不得徒手从垃圾中寻找锐器。锐器盒外表面被污染时应按生物或化学污染要求处理。'),
(11241, 1035, 1, '生物安全柜 使用 气流 操作 视窗 工作区', '生物安全柜使用前应检查气流、报警和玻璃视窗位置，待运行稳定后再开始操作。物品应放在工作区中部，避免挡住前后送风和排风格栅。操作动作应缓慢，减少手臂频繁进出造成气流扰动。'),
(11242, 1035, 2, '生物安全柜 紫外灯 明火 酒精灯 禁止 消毒', '紫外灯只用于无人时的表面照射，不能代替清洁和消毒，也应在人员进入前关闭。柜内不宜使用酒精灯等明火，以免扰乱气流和引发火灾。操作前后应使用适用消毒剂擦拭工作表面。'),
(11243, 1035, 3, '生物安全柜 故障 气流报警 维护 年检', '出现气流报警、风机异常、玻璃门损坏或压力异常时应停止使用并报告。设备应按规定进行维护和性能检测，维修后确认参数正常再启用。使用、消毒和故障情况应记录。'),
(11251, 1036, 1, '个人防护 护目镜 面屏 实验服 手套 选择', '进入实验室应穿合身的实验服和防滑鞋，长发束起，不佩戴垂挂饰品。涉及飞溅、腐蚀、粉尘或紫外线的操作应根据风险佩戴护目镜或面屏。普通近视眼镜不能替代密封护目镜，短裤、拖鞋和暴露皮肤的服装不得进入实验区域。'),
(11252, 1036, 2, '防化手套 丁腈 橡胶 兼容性 破损 更换', '选择手套前应核对化学品兼容性和操作时间，不能认为越厚越安全。手套应大小合适，污染、破损或接触不相容物质后立即更换。摘手套时避免手套外表面接触皮肤，操作结束后洗手。'),
(11253, 1036, 3, '呼吸防护 口罩 防毒面具 适用 训练', '普通医用口罩不能防护有机蒸气、酸性气体和缺氧环境。需要呼吸防护时应根据危害选择合适滤材，并经过培训和密合性检查。涉及未知浓度有毒气体或密闭空间时，应交由专业应急人员处理。'),
(11261, 1037, 1, '废弃物 分类 化学 生物 锐器 普通垃圾 标签', '实验室废弃物应按化学废液、化学固体、生物废物、锐器和普通垃圾分开收集，容器标明成分、危险性和日期。不同废液不得随意混合，未确认成分的废物应单独暂存并请管理员鉴别。'),
(11262, 1037, 2, '废液 容器 装量 密闭 泄漏 二次容器', '废液容器应使用相容材质并保持密闭，装量不宜过满，通常不超过容器容积的八成。容器应放在二次托盘或专用区域，防止倾倒泄漏。发现鼓胀、发热、异味或渗漏时应远离并报告。'),
(11263, 1037, 3, '废玻璃 锐器盒 生物废物 灭菌 转运 记录', '碎玻璃应单独收集并标注，污染锐器放入锐器盒，生物废物按规定灭菌后双层包装。废物转运时避免抛掷和挤压，交接应有记录。任何人不得把实验废物混入生活垃圾或带入公共区域。'),
(11271, 1038, 1, '实验台面 清洁 消毒 前后 污染 擦拭', '实验开始前应确认台面清洁、物品摆放有序，结束后及时清理样品、试剂和废弃物。清洁时应从污染风险较低的区域向较高区域擦拭，避免把污染物扩散到整个台面。抹布和刷子应按区域分开使用。'),
(11272, 1038, 2, '消毒剂 乙醇 含氯消毒剂 配比 接触时间 兼容', '选择消毒剂时应核对适用对象和浓度，按说明保证足够接触时间。含氯消毒剂不能与酸性清洁剂混合，乙醇应远离火源。消毒后需要清除残留的设备和表面，应按兼容性要求处理。'),
(11273, 1038, 3, '台面污染 泄漏 清洁 记录 通风', '台面被化学品或生物样本污染时，应先控制扩散并按相应泄漏流程处理，不能直接使用普通抹布反复擦拭。清洁完成后确认无气味、无可见污染并充分通风。污染范围较大时应记录并评估周围物品。'),
(11281, 1039, 1, '设备台账 使用记录 登记 仪器 状态 责任', '实验室设备应建立台账，记录名称、编号、责任人、启用日期、维护和校准情况。使用人员应按照规程登记使用时间、样品和运行状态。发现异常应停止使用并挂上故障提示，不能只用口头告知。'),
(11282, 1039, 2, '设备故障 维修 校准 停用 标签 确认', '设备出现异响、报警、温控异常或结果漂移时应停止使用，保持必要证据并报告管理员。维修或校准后应确认功能和参数恢复正常，再由授权人员解除停用状态。不得擅自拆开带电或带压设备。'),
(11283, 1039, 3, '实验记录 追溯 原始数据 日期 签名 修改', '实验记录应及时、真实、完整，包含日期、人员、样品、条件、结果和异常情况。修改原始记录时应保留原内容并说明原因，不得覆盖或编造数据。电子数据应备份并控制访问权限，便于追溯。'),
(11291, 1040, 1, '实验前 风险评估 危害 识别 步骤 应急', '开展新实验前应进行风险评估，识别化学品、设备、生物、电气和火灾危害，明确操作步骤、个人防护和应急处置。涉及高温、高压、有毒、易燃或未知材料时，应经指导教师审核后再操作。'),
(11292, 1040, 2, '实验准入 培训 安全考试 考核 授权 操作证', '进入实验室前应完成安全培训、考试和实验室准入要求，熟悉疏散路线、洗眼器、灭火器和急救设备的位置。未经授权不得独立操作大型设备或危险化学品。人员变更操作内容时应补充相应培训。'),
(11293, 1040, 3, '应急预案 联系 报告 单人实验 高危实验', '高风险实验不得单人进行，应保持至少两人在场并保证通讯畅通。实验前确认指导教师、实验室管理员和校园应急电话，准备好泄漏、火灾、受伤等情况的处置方案。任何事故和险情都应报告，不能隐瞒。')
